{
  "rules": [
    {
      "rule_id": "R001",
      "rule": "Pedestrians walk at a steady, casual pace across the paved plaza.",
      "source_description_ids": [
        "D01N_01_002_C00",
        "D01N_01_003_C00"
      ]
    },
    {
      "rule_id": "R002",
      "rule": "Individuals traverse the open space in continuous, linear paths.",
      "source_description_ids": [
        "D01N_01_003_C00",
        "D01N_01_005_C01"
      ]
    },
    {
      "rule_id": "R003",
      "rule": "Pedestrians maintain personal space while passing others without direct interaction.",
      "source_description_ids": [
        "D01N_01_002_C01",
        "D01N_01_005_C01"
      ]
    },
    {
      "rule_id": "R004",
      "rule": "People carry personal items like backpacks, bags, or umbrellas while walking.",
      "source_description_ids": [
        "D01N_01_002_C00",
        "D01N_01_005_C00"
      ]
    },
    {
      "rule_id": "R005",
      "rule": "Individuals walk side-by-side or in small, loose groups.",
      "source_description_ids": [
        "D01N_01_002_C00",
        "D01N_01_007_C01"
      ]
    },
    {
      "rule_id": "R006",
      "rule": "Some pedestrians look down at handheld devices while walking.",
      "source_description_ids": [
        "D01N_01_002_C00",
        "D01N_01_016_C00"
      ]
    },
    {
      "rule_id": "R007",
      "rule": "Walking behavior is consistent without sudden stops or erratic movements.",
      "source_description_ids": [
        "D01N_01_002_C00",
        "D01N_01_003_C00"
      ]
    },
    {
      "rule_id": "R008",
      "rule": "Pedestrians navigate around static features like manhole covers and trash bins.",
      "source_description_ids": [
        "D01N_01_002_C01",
        "D01N_01_003_C00"
      ]
    },
    {
      "rule_id": "R009",
      "rule": "Individuals walk near the edge of grassy areas or curbs.",
      "source_description_ids": [
        "D01N_01_002_C00",
        "D01N_01_003_C01"
      ]
    },
    {
      "rule_id": "R010",
      "rule": "Small groups may stand briefly near the walkway edge.",
      "source_description_ids": [
        "D01N_01_003_C01",
        "D01N_01_067_C01"
      ]
    },
    {
      "rule_id": "R011",
      "rule": "Pedestrians move in various directions, including towards or away from camera.",
      "source_description_ids": [
        "D01N_01_022_C00",
        "D01N_01_029_C00"
      ]
    },
    {
      "rule_id": "R012",
      "rule": "Casual recreational activities like kicking a ball occur in open areas.",
      "source_description_ids": [
        "D01N_01_016_C01",
        "D01N_01_068_C01"
      ]
    }
  ]
}

